    /// <summary>
    /// MPJ_22974_BMSProductMDRItemStatusAndPackChange by chaminda on 27 Apr 2022
    /// Finds the specified record in the <c>METItemStatusTable</c> table.
    /// </summary>
    /// <param name="_metItemStatus">
    /// The ItemStatus of the <c>METItemStatusTable</c> record to find.
    /// </param>
    /// <param name="_update">
    /// A Boolean value that indicates whether to read the record for update; optional.
    /// </param>
    /// <returns>
    /// A record in the <c>METItemStatusTable</c> table; otherwise, an empty record.
    /// </returns>
    public static METItemStatusTable find(
        METItemStatus      _metItemStatus,
        boolean     _update = false)
    {
        METItemStatusTable  metItemStatusTable;

        metItemStatusTable.selectForUpdate(_update);

        if (_metItemStatus)
        {
            select firstonly metItemStatusTable
                where metItemStatusTable.ItemStatus == _metItemStatus;
        }

        return metItemStatusTable;
    }

    /// <summary>
    /// Find the specified record in the table
    /// </summary>
    /// <param name = "_metItemsStatus">Enum METItemsStatus</param>
    /// <param name = "_update">Boolean Update</param>
    /// <returns></returns>
    public static METItemStatusTable findByStatus(
        METItemsStatus      _metItemsStatus,
        boolean     _update = false)
    {
        METItemStatusTable  metItemStatusTable;

        metItemStatusTable.selectForUpdate(_update);        
       
        select firstonly metItemStatusTable
            where metItemStatusTable.Status == _metItemsStatus;       

        return metItemStatusTable;
    }

    /// <summary>
    /// Validate method before Insert
    /// </summary>
    /// <returns>boolean</returns>
    public boolean validateWrite()
    {
        boolean ret;
        METItemStatusTable metItemStatusTable;
    
        ret = super();

        select firstonly RecId from metItemStatusTable
            where metItemStatusTable.Status == this.Status;
        if (metItemStatusTable && !this.RecId)
        {
            ret = checkFailed("@SYS35524");
        }
    
        return ret;
    }

    /// <summary>
    /// Validate method before delete
    /// </summary>
    /// <returns></returns>
    public boolean validateDelete()
    {
        METInventItemOrderSetup metInventItemOrderSetup;

        boolean ret;
    
        ret = super();

        select firstonly RecId, ItemId from metInventItemOrderSetup
            where metInventItemOrderSetup.ItemStatus == this.ItemStatus;

        if(metInventItemOrderSetup)
        {
            ret = checkFailed(strFmt("@MET:ItemStatusDeleteValidation", metInventItemOrderSetup.ItemId));
        }
    
        return ret;
    }
